        // The reference contract returns ownerAddr; the buggy one returns debtAddr
        address actualOwner = cooler.owner();
        assertTrue(actualOwner == ownerAddr);
    }

    // Minimal clone deployment helper equivalent to ClonesWithImmutableArgs.clone
    function deployClone(address implementation, bytes memory data) internal returns (address payable instance) {
        uint256 extraLength = data.length + 2;
        uint256 creationSize = 0x41 + extraLength;
        uint256 runSize = creationSize - 10;
        uint256 dataPtr;
