import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address whatever) public {
        // owner() must return the first immutable arg (offset 0x0), not the factory arg (offset 0x3c).
        // In the reference version, owner is the address that generated the cooler, which is the msg.sender
        // of the factory at clone time. Since we deploy C directly rather than via the factory,
        // the immutable args are empty/uninitialized, but the relative offsets still differ:
        // reference: owner returns calldata at offset+0x0;
        // bug: owner returns calldata at offset+0x3c (factory slot).
        // So for ANY input, the two return values must differ (calldata at different positions in uninitialized clone data).
        // Assert that owner() does NOT equal factory().
        assertTrue(c.owner() != c.factory());
    }
}

