import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address deployer, address factoryAddr) public {
        vm.assume(deployer != factoryAddr);
        // The immutable args are baked during clone construction.
        // We cannot directly set them after new C(), but the invariant is:
        // owner() returns the real owner (offset 0x0) and factory() returns the factory (offset 0x3c).
        // Since the bug makes owner() return the factory address, we must check that owner() != factory()
        // under all circumstances where deployer != factory address.
        // However, in the test, c is a base deployment, not a clone. The base C has no immutable args set
        // by ClonesWithImmutableArgs. The _getArgAddress returns zero-address for unfilled slots.
        // But the bug swaps offset 0x0 with 0x3c, so owner() would return the factory's address if set.
        // To properly fuzz, we need the clone scenario. We'll deploy a minimal clone factory to set the
        // immutable args correctly, then test the invariant on the cloned instance.
    }
}

contract CloneFactory {
    using ClonesWithImmutableArgs for address;
    address public immutable implementation;
    constructor() { implementation = address(new C()); }
    function clone(address owner, address collateral, address debt, address factory) external returns (address) {
        bytes memory data = abi.encodePacked(owner, collateral, debt, factory);
        return implementation.clone(data);
    }
}

