contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address collat, address debt, address factory) public {
        vm.assume(owner != address(0));
        vm.assume(collat != address(0));
        vm.assume(debt != address(0));
        vm.assume(factory != address(0));
        vm.assume(collat != debt);

        bytes memory data = abi.encodePacked(owner, collat, debt, factory);
        vm.etch(address(c), type(CloneHarness).creationCode);
        (bool ok, ) = address(c).call(abi.encodePacked(data));
        require(ok, "deploy clone failed");

        assertTrue(address(c.collateral()) == collat);
    }
