contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 dummy) public {
        // The mutation changes collateral() to return the debt token address (offset 0x28)
        // instead of the collateral token address (offset 0x14).
        // In any deployment where the collateral and debt tokens are different addresses,
        // collateral() should return the collateral token, not the debt token.
        // The factory deployment encodes owner, collateral, debt, factory addresses.
        // The correct collateral() returns the address at offset 0x14, which is the collateral token.
        // The buggy version returns the address at offset 0x28, which is the debt token.
        // Therefore, collateral() should not equal the debt token address when collateral != debt.
        // The fuzzer controls dummy to avoid optimization, but we need to deploy a clone with different
        // collateral and debt addresses to trigger the bug. Since C is a Clone, we need a factory-like
        // deployment to set immutable args. We'll deploy a minimal factory that clones C with controlled args.
        // But to keep the test simple and respect the constraint that c is deployed as `new C()` in setUp,
        // the immutable args of c are all zero addresses. In that case, collateral == debt == address(0),
        // so the bug would not manifest. To create a scenario where collateral != debt, we must deploy
        // a clone with distinct addresses. We can do this within the test by using the ClonesWithImmutableArgs
        // library to clone the implementation. However, the test requires c to be the instance under test.
        // We'll deploy a fresh clone for the fuzz test.
        // Since the mutation is in the Clone contract's collateral() function, we need an instance where
        // the immutable args have different collateral and debt addresses.
        // We'll deploy a new C implementation, then clone it with different addresses.

        // Use two dummy token addresses that are unequal.
        address collateralToken = address(uint160(1));
        address debtToken = address(uint160(2));
        // Ensure they are different.
        require(collateralToken != debtToken, "Tokens must differ");

        // Deploy a new implementation for cloning.
        C implementation = new C();

        // Prepare data for clone: owner, collateral, debt, factory
        bytes memory data = abi.encodePacked(address(this), collateralToken, debtToken, address(this));

        // Use the library to clone (we'll inline the clone logic since we can't import the library).
        // Alternatively, we can use the library directly if it's available, but to keep self-contained,
        // we implement the clone call. Since the library is internal, we'll simulate it.
        // However, ClonesWithImmutableArgs is part of the same source? The contract under test is C,
        // which uses Clone and the library is in the same file. But we cannot import the library directly.
        // We'll manually call the clone function by copying the assembly from the library.
        // To avoid reinventing, we can deploy a minimal factory that uses the library to clone.
        // Since the library is accessible in the original source but not imported here,
        // we'll assume the library bytecode is available? No, we must be self-contained.
        // The simplest: The property we test is on the `collateral()` function of a Clone contract.
        // We can deploy a clone by using the `create2` with the init code? The Clone contract
        // reads immutable args from calldata after the creation code. The library creates the clone.
        // We'll just deploy a minimal proxy that uses the clone logic.
        // Actually, the C contract inherits Clone, and the factory uses ClonesWithImmutableArgs.
        // We can directly call C's clone function? No, it's a library function.
        // We'll deploy a helper factory contract that does the clone for us.
        // To stay within constraints, we'll add a helper contract after InvMutTest.
        // The helper will clone C with given parameters and return the address.
        // Then we test the returned instance's collateral() against the debt token.

        // Deploy a Cloner helper that can clone C with given args.
        Cloner cloner = new Cloner();
        // Clone C with different collateral and debt tokens.
        address cloneAddr = cloner.cloneC(collateralToken, debtToken);
        C clone = C(cloneAddr);

        // The correct behavior: collateral() returns collateralToken.
        // The buggy behavior: collateral() returns debtToken.
        // Since collateralToken != debtToken, collateral() should NOT equal debtToken.
        assertTrue(clone.collateral() != ERC20(debtToken));
    }
