// Minimal helper to clone C with given collateral and debt token addresses.
contract Cloner {
    using ClonesWithImmutableArgs for address;

    function cloneC(address collateral, address debt) external returns (address payable clone) {
        C implementation = new C();
        bytes memory data = abi.encodePacked(address(this), collateral, debt, address(this));
        clone = address(implementation).clone(data);
    }
}
